// Atropine crosses the blood-brain barrier and blocks central muscarinic receptors.
// Every frame is computed from t only; routes are sampled once in setup.
const HEX = "0,-9.5 8.23,-4.75 8.23,4.75 0,9.5 -8.23,4.75 -8.23,-4.75";
const CUPS = [190, 230, 270, 310], MEM = 310, DOCK_Y = 292;
const CUP_D = "M -15 0 L -15 -21 Q -15 -26 -10.5 -26 L -9.5 -26 C -9.5 -9, 9.5 -9, 9.5 -26 L 10.5 -26 Q 15 -26 15 -21 L 15 0 Z";
const W = [[126, 266], [103, 290], [127, 314], [104, 338]];   // waiting spots at the cleft entrance
let E = {};
function route(pts) {                       // Catmull-Rom through pts, arc-length parametrised
  const s = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
    for (let k = 0; k < 20; k++) {
      const u = k / 20, u2 = u * u, u3 = u2 * u;
      const f = (a, b, c, d) => 0.5 * (2 * b + (-a + c) * u + (2 * a - 5 * b + 4 * c - d) * u2 + (-a + 3 * b - 3 * c + d) * u3);
      s.push([f(p0[0], p1[0], p2[0], p3[0]), f(p0[1], p1[1], p2[1], p3[1])]);
    }
  }
  s.push(pts[pts.length - 1]);
  const L = [0];
  for (let i = 1; i < s.length; i++) L.push(L[i - 1] + Math.hypot(s[i][0] - s[i - 1][0], s[i][1] - s[i - 1][1]));
  const tot = L[L.length - 1];
  return f => {
    const d = Math.max(0, Math.min(1, f)) * tot;
    let lo = 0, hi = L.length - 1;
    while (hi - lo > 1) { const m = (lo + hi) >> 1; if (L[m] <= d) lo = m; else hi = m; }
    const u = L[hi] > L[lo] ? (d - L[lo]) / (L[hi] - L[lo]) : 0;
    return [s[lo][0] + (s[hi][0] - s[lo][0]) * u, s[lo][1] + (s[hi][1] - s[lo][1]) * u];
  };
}
function hex(api, parent) {
  const g = api.el("g", {}, parent);
  api.el("polygon", {points: HEX, fill: "url(#atrFill)", stroke: "#3c0d6b", "stroke-width": 1.5, "stroke-linejoin": "round"}, g);
  return g;
}
function chip(api, parent, x, y, w, stroke) {
  const g = api.el("g", {opacity: 0}, parent);
  const b = api.el("g", {filter: "url(#chipShadow)"}, g);
  api.el("rect", {x: x - w / 2, y: y - 15, width: w, height: 30, rx: 15, fill: "#ffffff", stroke: stroke, "stroke-width": 1.5}, b);
  return g;
}
function txt(api, parent, s, attrs) {
  const t = api.el("text", Object.assign({"font-family": "system-ui,sans-serif", "font-size": 18, "font-weight": 700}, attrs), parent);
  t.textContent = s; return t;
}
function setup(api) {
  const rnd = api.random(9402);
  // blood: red cells (two lanes) and atropine circulating with them
  const blood = api.$("#blood");
  E.rbc = [];
  for (let i = 0; i < 9; i++) {
    const lane = i % 2;
    E.rbc.push({el: api.el("use", {href: "#rbc"}, blood), x0: i * 74 + rnd() * 20, y: lane ? 516 : 478,
      v: lane ? 34 : 42, a: rnd() * 60 - 30, s: 0.82 + rnd() * 0.12});
  }
  E.bg = [];
  for (let i = 0; i < 3; i++) E.bg.push({el: hex(api, blood), x0: 330 + i * 120 + rnd() * 30, y: i % 2 ? 494 : 500, ph: rnd() * 6});
  // receptor cups
  E.cups = CUPS.map(x => api.el("path", {d: CUP_D, transform: "translate(" + x + " " + MEM + ")", fill: "#2a9d8f", stroke: "#17675e", "stroke-width": 1.6, "stroke-linejoin": "round"}, api.$("#cups")));
  // atropine molecules that cross the barrier: four reach the cleft, two stay in the brain tissue
  const atr = api.$("#atr");
  const R1 = [
    [[38, 494], [58, 472], [62, 430], [64, 394], [86, 330], [126, 266]],
    [[64, 522], [100, 500], [112, 466], [112, 430], [110, 392], [103, 290]],
    [[104, 484], [150, 476], [168, 450], [168, 428], [158, 392], [130, 368], [127, 314]],
    [[150, 514], [208, 504], [236, 468], [236, 428], [228, 392], [180, 388], [140, 372], [104, 338]],
    [[206, 486], [262, 480], [282, 456], [282, 428], [278, 396], [270, 387]],
    [[268, 518], [326, 506], [352, 466], [352, 428], [346, 396], [336, 389]]];
  const T1 = [[300, 2150], [420, 2300], [520, 2420], [600, 2560], [460, 2000], [560, 2150]];
  E.mol = R1.map((pts, i) => ({el: hex(api, atr), r1: route(pts), t1: T1[i], ph: rnd() * 6}));
  // beat 2: into the cleft and down into a cup (farthest cup first)
  const T2 = [[2800, 3700], [2950, 3820], [3100, 3920], [3250, 4000]];
  for (let i = 0; i < 4; i++) {
    const cx = CUPS[3 - i], w = W[i];
    E.mol[i].r2 = route([w, [148, 263], [cx - 18, 263], [cx, 274], [cx, DOCK_Y]]);
    E.mol[i].t2 = T2[i];
    E.mol[i].cup = 3 - i;
  }
  // ACh released from the terminal; it reaches the cups after atropine and bounces off
  const ach = api.$("#ach");
  E.ach = [];
  for (let j = 0; j < 8; j++) {
    const k = j % 4, side = j < 4 ? -1 : 1;
    const dockEnd = T2[3 - k][1];
    E.ach.push({el: api.el("circle", {r: 5, fill: "#2a9d8f", stroke: "#17675e", "stroke-width": 1}, ach),
      x0: CUPS[k] + side * 7 + (rnd() * 6 - 3), y0: 246, k: k, side: side,
      tIn: 2850 + j * 30, tHit: dockEnd + 120 + j * 25, bx: side * (5 + rnd() * 3), by: (side < 0 ? 249 : 260) + rnd() * 3, ph: rnd() * 6});
  }
  // "atropine" legend chip in the blood
  const chips = api.$("#chips");
  E.atrChip = chip(api, chips, 520, 495, 132, "#cdb0ea");
  const ic = hex(api, E.atrChip); api.set(ic, {transform: "translate(474 495) scale(0.9)"});
  txt(api, E.atrChip, "atropine", {x: 488, y: 501, fill: "#5a189a"});
  // "blocked" chip inside the postsynaptic cell
  E.blk = chip(api, chips, 250, 337, 118, "#e8b4ad");
  api.el("circle", {cx: 210, cy: 337, r: 8, fill: "none", stroke: "#c0392b", "stroke-width": 2.6}, E.blk);
  api.el("line", {x1: 204.5, y1: 342.5, x2: 215.5, y2: 331.5, stroke: "#c0392b", "stroke-width": 2.6, "stroke-linecap": "round"}, E.blk);
  txt(api, E.blk, "blocked", {x: 224, y: 343, fill: "#c0392b"});
  E.brainGrey = api.$("#brainGrey"); E.haze = api.$("#haze"); E.q = api.$("#qmark"); E.cog = api.$("#cogLabel");

}
function render(t, api) {
  const s = t / 1000;
  // blood flow (continuous)
  for (const c of E.rbc) {
    const x = ((c.x0 + c.v * s) % 680) - 20;
    api.set(c.el, {transform: "translate(" + x.toFixed(1) + " " + c.y + ") rotate(" + c.a.toFixed(0) + ") scale(" + c.s.toFixed(2) + ")"});
  }
  const bgIn = api.seg(t, 200, 500, "ease_out");
  for (const b of E.bg) {
    const x = ((b.x0 + 40 * s) % 680) - 20, y = b.y + 4 * Math.sin(s * 2 + b.ph);
    api.set(b.el, {transform: "translate(" + x.toFixed(1) + " " + y.toFixed(1) + ")", opacity: bgIn.toFixed(3)});
  }
  // 1. atropine leaves the blood, passes through the endothelial cells and enters brain tissue
  E.mol.forEach((m, i) => {
    const appear = api.seg(t, 200 + i * 50, 500 + i * 50, "ease_out");
    let p = m.r1(api.seg(t, m.t1[0], m.t1[1], "ease_in_out"));
    let wob = 1 - api.seg(t, m.t1[1] - 300, m.t1[1], "linear");
    if (m.r2) {
      const k = api.seg(t, m.t2[0], m.t2[1], "ease_in_out");
      if (k > 0) p = m.r2(k);
      wob = 0;
    }
    const jx = wob * 1.5 * Math.sin(s * 5 + m.ph), jy = wob * 1.5 * Math.cos(s * 4 + m.ph);
    const rest = m.r2 ? 0 : api.seg(t, m.t1[1], m.t1[1] + 400, "linear");
    const bx = rest * 2 * Math.sin(s * 2.2 + m.ph), by = rest * 2 * Math.cos(s * 1.8 + m.ph);
    api.set(m.el, {transform: "translate(" + (p[0] + jx + bx).toFixed(1) + " " + (p[1] + jy + by).toFixed(1) + ") scale(" + (0.6 + 0.4 * appear).toFixed(3) + ")", opacity: appear.toFixed(3)});
    if (m.r2) {
      const dk = api.seg(t, m.t2[1] - 150, m.t2[1] + 200, "ease_out");
      api.set(E.cups[m.cup], {fill: api.mixColor("#2a9d8f", "#3b4651", dk), stroke: api.mixColor("#17675e", "#1f2830", dk)});
    }
  });
  const chipK = api.seg(t, 300, 700, "ease_out");
  api.set(E.atrChip, {opacity: chipK.toFixed(3), transform: "translate(0 " + ((1 - chipK) * 8).toFixed(1) + ")"});
  // 2. ACh is released, reaches the occupied cups and bounces off
  for (const a of E.ach) {
    const vis = api.seg(t, a.tIn, a.tIn + 250, "ease_out");
    const fall = api.seg(t, a.tIn + 150, a.tHit, "ease_in");
    const hitY = DOCK_Y - 9.5 - 5;
    let x = a.x0, y = a.y0 + (hitY - a.y0) * fall;
    const b = api.seg(t, a.tHit, a.tHit + 500, "ease_out");
    if (b > 0) { x = a.x0 + a.bx * b; y = hitY + (a.by - hitY) * b; }
    const drift = api.seg(t, a.tHit + 500, a.tHit + 900, "linear");
    x += drift * 3 * Math.sin(s * 2.4 + a.ph); y += drift * 2 * Math.cos(s * 2 + a.ph);
    api.set(a.el, {cx: x.toFixed(1), cy: y.toFixed(1), opacity: vis.toFixed(3)});
  }
  const bk = api.seg(t, 4150, 4500, "back_out");
  api.set(E.blk, {opacity: Math.min(1, bk * 1.4).toFixed(3), transform: "translate(250 337) scale(" + (0.6 + 0.4 * bk).toFixed(3) + ") translate(-250 -337)"});
  // 3. central anticholinergic effect: the brain greys, haze, "?"
  const g = api.seg(t, 5100, 6100, "ease_in_out");
  api.set(E.brainGrey, {opacity: g.toFixed(3)});
  api.set(E.haze, {opacity: api.seg(t, 5200, 6200, "ease_in_out").toFixed(3)});
  const q = api.seg(t, 5450, 5900, "back_out");
  api.set(E.q, {opacity: Math.min(1, q * 1.5).toFixed(3), transform: "translate(572 158) scale(" + (0.4 + 0.6 * q).toFixed(3) + ") translate(-572 -158)"});
  const c = api.seg(t, 5650, 6150, "ease_out");
  api.set(E.cog, {opacity: c.toFixed(3), transform: "translate(0 " + ((1 - c) * 8).toFixed(1) + ")"});
}
